  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const counts = new Map()
    for (const c of continuing) counts.set(c, 0n)
    let activeTotal = 0n
    for (const ballot of ballots) {
      const pick = ballot.ranking.find((name) => continuing.has(name))
      if (pick !== undefined) {
        counts.set(pick, counts.get(pick) + ballot.count)
        activeTotal += ballot.count
      }
    }
    history.push(counts)

    let roundWinner = null
    if (activeTotal > 0n) {
      for (const name of continuing) {
        if (counts.get(name) * 2n > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    let eliminated = null
    if (roundWinner === null && activeTotal > 0n) {
      eliminated = selectElimination(continuing, counts, history)
      continuing.delete(eliminated)
    }

    rounds.push({
      counts: sortedCounts(counts),
      exhausted: totalBallots - activeTotal,
      eliminated,
      winner: roundWinner,
    })

    if (roundWinner !== null || activeTotal === 0n) {
      winner = roundWinner
      break
    }
  }

  return { rounds, winner }
