  const entries = [...counts.entries()]
  entries.sort((a, b) => {
    if (a[1] !== b[1]) return a[1] > b[1] ? -1 : 1
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  return entries
}

