  let minVal = null
  for (const name of continuing) {
    const v = counts.get(name)
    if (minVal === null || v < minVal) minVal = v
  }
  let tied = [...continuing].filter((name) => counts.get(name) === minVal)

  while (tied.length > 1) {
    let separated = false
